using Seasonote;
using Windows.Media.Control;
using Windows.Storage.Streams;
using System.Collections.Concurrent;
using S = Windows.Media.Control.GlobalSystemMediaTransportControlsSessionPlaybackStatus;
var snapshots = new ConcurrentQueue<Dictionary<string,object?>>();
Dictionary<string,object?> latest = new();
var m = GlobalSystemMediaTransportControlsSessionManager.Instance;
using var bridge = new MusicBridge();
bridge.StateChanged += state => { latest=state;snapshots.Enqueue(state); };
await bridge.StartAsync();
async Task Until(Func<bool> predicate,string label,int ms=5000){var until=DateTime.UtcNow.AddMilliseconds(ms);while(!predicate()){if(DateTime.UtcNow>until)throw new Exception("FAIL "+label);await Task.Delay(20);}Console.WriteLine("PASS "+label);}
void Check(bool value,string label){if(!value)throw new Exception("FAIL "+label);Console.WriteLine("PASS "+label);}
await Until(()=>latest.TryGetValue("connected",out var c)&&c is false,"no-player ornament state");
Check(latest["title"] is ""&&latest["duration"] is null&&latest["artwork"] is null,"empty metadata clears artwork/timeline");
var qq=new GlobalSystemMediaTransportControlsSession();m.Replace(qq);
await Task.Delay(150);Check(latest["connected"] is false,"installed but no title stays ornament");
qq.Media=new(){Title="Track A",Artist="Singer A",Thumbnail=new Thumbnail([0x89,0x50,0x4e,0x47,1,2,3,4])};qq.Playback.PlaybackStatus=S.Playing;qq.MediaChanged();
await Until(()=>latest["connected"] is true && latest["title"] is "Track A","newly-started QQ auto-connects without restart");
await Until(()=>snapshots.Any(s=>s.TryGetValue("artwork",out var a)&&a is string),"cover art is emitted");
var play1=(double)latest["position"]!;await Task.Delay(650);Check((double)latest["position"]!>play1,"playing timeline advances");
qq.Playback.PlaybackStatus=S.Paused;qq.Timeline.Position=TimeSpan.FromSeconds(31);qq.PlaybackChanged();
await Until(()=>latest["playing"] is false && latest["position"] is double p && p==31,"pause retains panel and exact position");
await Task.Delay(650);Check((double)latest["position"]! ==31 && latest["connected"] is true,"paused timeline remains fixed");
qq.Playback.Controls.IsPlayPauseToggleEnabled=false;await bridge.CommandAsync("toggle");Check(qq.Commands.Last().Item1=="play","toggle falls back to supported play");
qq.Playback.Controls.IsNextEnabled=false;qq.PlaybackChanged();await Task.Delay(100);var count=qq.Commands.Count;await bridge.CommandAsync("next");Check(qq.Commands.Count==count,"unsupported commands never sent");
qq.Timeline.StartTime=TimeSpan.FromSeconds(10);qq.Timeline.EndTime=TimeSpan.FromSeconds(190);await bridge.CommandAsync("seek",42);Check(qq.Commands.Last()==("seek",TimeSpan.FromSeconds(52).Ticks),"seek maps relative progress to source timeline");
count=qq.Commands.Count;await bridge.CommandAsync("seek",double.NaN);await bridge.CommandAsync("seek",-1);await bridge.CommandAsync("seek",99999);Check(qq.Commands.Count==count,"invalid seek values rejected");
var delayed = new Thumbnail([0x89,0x50,0x4e,0x47,10,20,30,40],1000);
qq.Media=new(){Title="Delayed Old",Thumbnail=delayed};qq.MediaChanged();await Until(()=>latest["title"] is "Delayed Old","delayed track metadata published");
qq.Media=new(){Title="Current B",Thumbnail=new Thumbnail([0xff,0xd8,0xff,9,8,7])};qq.MediaChanged();await Until(()=>latest["title"] is "Current B","new track replaces old asynchronously");
var after=snapshots.Count;await Task.Delay(1300);var tail=snapshots.Skip(after).ToArray();Check(!tail.Any(s=>s.TryGetValue("artwork",out var a)&&a is string str&&str.EndsWith(Convert.ToBase64String([0x89,0x50,0x4e,0x47,10,20,30,40]))),"late old artwork cannot overwrite new track");
var browser=new GlobalSystemMediaTransportControlsSession{SourceAppUserModelId="Browser",Media=new(){Title="Video"}};browser.Playback.PlaybackStatus=S.Playing;
qq.Playback.PlaybackStatus=S.Paused;m.Replace(qq,browser);
await Until(()=>latest["source"] is "Browser","playing source supersedes paused system session");
qq.MetadataDelay=600;qq.Media=new(){Title="Stale Source"};qq.Playback.PlaybackStatus=S.Playing;m.Replace(qq);await Task.Delay(100);m.Replace(browser);
await Task.Delay(850);Check(latest["source"] is "Browser","late metadata cannot resurrect switched source");
m.Replace();await Until(()=>latest["connected"] is false && latest["source"] is "","player exit returns ornament");
bridge.PublishCurrentState();Check(latest.ContainsKey("artwork")&&latest["artwork"] is null,"reloaded web document receives clear artwork");
qq.MetadataDelay=0;m.Replace(qq);await Until(()=>latest["connected"] is true,"reconnect after exit");
bridge.Dispose();count=snapshots.Count;m.Replace();qq.MediaChanged();await bridge.CommandAsync("play");await bridge.StartAsync();await Task.Delay(650);Check(snapshots.Count==count,"dispose prevents queued and future callbacks");
Console.WriteLine("ALL PASS (actual MusicBridge source, fake SMTC; not Windows runtime test)");
